def closest_sum(a, t):
    if len(a) < 2:
        return None
    i, j = 0, len(a) - 1
    best = abs(a[i] + a[j] - t)
    while i < j:
        s = a[i] + a[j]
        best = min(best, abs(s - t))
        if s < t:
            i += 1
        elif s > t:
            j -= 1
        else:
            return 0
    return best

