def longest_k_kinds(s, k):
    count = {}
    left = best = 0
    for right, ch in enumerate(s):
        count[ch] = count.get(ch, 0) + 1
        while len(count) > k:
            out = s[left]
            count[out] -= 1
            if count[out] == 0:
                del count[out]
            left += 1
        best = max(best, right - left + 1)
    return best

problems.brute:
def longest_k_kinds(s, k):
    best = 0
    for i in range(len(s)):
        kinds = set()
        for j in range(i, len(s)):
            kinds.add(s[j])
            if len(kinds) > k:
                break
            best = max(best, j - i + 1)
    return best

